example.point:
▶️ ALGORITHM Inverse ;
VAR number : Real ;
BEGIN
  WRITE('Give a number: ');
  READ(number);
  WRITE('The inverse of the number: ', number, ' is: ', 1/number);
END.

▶️ ALGORITHM absolute_value;
VAR Number : Integer ;
BEGIN
  READ(number) ;
  IF (number < 0) THEN
    number <- -(number) ;
  END IF ;
  WRITE('The absolute value is', number) ;
END.

▶️ ALGORITHM InverseComplete ;
VAR number: Real ;
BEGIN
  WRITE('Give a number') ;
  READ(number) ;
  IF (number <> 0) THEN
    WRITE('The inverse of the number: ', number, ' is: ', 1/number) ;
  END IF ;
  IF (number = 0) THEN
    WRITE('the entered number is zero') ;
  END IF ;
END.

syntax.point:
🔀 IF (condition) THEN
  Processing 1 ;
ELSE
  Processing 2 ;
END IF ;

example.point:
▶️ ALGORITHM InverseAltcomplete;
VAR number : Real ;
BEGIN
  READ(number) ;
  IF (number <> 0) THEN
    WRITE('The inverse of the number: ', number, ' is: ', 1/number) ;
  ELSE
    WRITE('the introduced number is zero') ;
  END IF ;
END.

▶️ ALGORITHM Observation ;
VAR Average : Real ;
BEGIN
  READ(Average) ;
  IF (Average >= 10) THEN
    WRITE('Admitted') ;
  ELSE
    IF (Average >= 9.5) THEN
      WRITE('Remedial') ;
    ELSE
      WRITE('Failed') ;
    END IF ;
  END IF ;
END.

syntax.point:
🔀 CASE (expression) OF
  CASE C1 : Processing 1 ;
  CASE C2 : Processing 2 ;
  CASE C3 : Processing 3 ;
  ...
  CASE CN : Processing N ;
  DEFAULT : Processing (N+1) ;
END CASE ;

🔀 switch (expression) {
  case C1 : Processing 1 ; break;
  case C2 : Processing 2 ; break;
  case C3 : Processing 3 ; break;
  ...
  case CN : Processing N ; break;
  default : Processing (N+1) ;
}

example.point:
▶️ ALGORITHM days_month ;
VAR month : Integer ;
BEGIN
  WRITE('Which month is it?');
  READ(month) ;
  CASE (month) OF
    CASE 1, 3, 5, 7, 8, 10, 12 : WRITE('Number of days: 31') ;
    CASE 4, 6, 9, 11 : WRITE('Number of days: 30') ;
    CASE 2 : WRITE('Number of days: 28 or 29') ;
    DEFAULT WRITE('This month does not exist') ;
  END CASE ;
END.
